def max_profit(prices):
    hold, sold, rest = float('-inf'), 0, 0
    for p in prices:
        # buy only from rest; sell from hold; rest after a sale or a rest
        hold, sold, rest = max(hold, rest - p), hold + p, max(rest, sold)
    return max(sold, rest)

from functools import lru_cache

def max_profit(prices):
    @lru_cache(maxsize=None)
    def best(i, holding):              # best profit from day i on
        if i >= len(prices):
            return 0
        wait = best(i + 1, holding)
        if holding:
            return max(wait, prices[i] + best(i + 2, False))   # sell, then cool down
        return max(wait, -prices[i] + best(i + 1, True))       # buy

    return best(0, False)

