def num_decodings(s):
    two, one = 1, (0 if s[0] == '0' else 1)   # ways for s[:i-2], s[:i-1]
    for i in range(2, len(s) + 1):
        cur = 0
        if s[i - 1] != '0':
            cur += one                 # last digit alone
        if 10 <= int(s[i - 2:i]) <= 26:
            cur += two                 # last two digits together
        two, one = one, cur
    return one

