from functools import lru_cache

def num_decodings(s):
    @lru_cache(maxsize=None)
    def ways(i):                       # ways to decode s[i:]
        if i == len(s):
            return 1
        if s[i] == '0':
            return 0                   # no letter starts with 0
        total = ways(i + 1)
        if i + 1 < len(s) and int(s[i:i + 2]) <= 26:
            total += ways(i + 2)
        return total

    return ways(0)

