def min_cost_climbing_stairs(cost):
    n = len(cost)
    dp = [0] * (n + 1)                 # dp[i]: min cost to stand on step i
    for i in range(2, n + 1):
        dp[i] = min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2])
    return dp[n]

